SELECT budget_bucket, location, stddev_budget FROM (SELECT CASE WHEN budget >= 3264000 THEN 'high' WHEN budget >= 1602000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, ROUND(STDDEV(budget), 2) AS stddev_budget FROM departments GROUP BY CASE WHEN budget >= 3264000 THEN 'high' WHEN budget >= 1602000 THEN 'mid' ELSE 'low' END, location) AS t WHERE stddev_budget < 58 ORDER BY location;
